import{z as A,x as B,o as E,c as l,q as r,j as s,D as e,d as o,s as c,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Spectre v1 / v2","description":"","frontmatter":{"title":"Spectre v1 / v2","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spectre-variants.md","filePath":"cs/spectre-variants.md","lastUpdated":1791063341000}'),p={name:"cs/spectre-variants.md"};function i(d,a,h,v,_,T){const t=B("Mermaid");return E(),l("div",null,[a[2]||(a[2]=r('<h1 id="spectre-v1-v2" tabindex="-1">Spectre v1 / v2 <a class="header-anchor" href="#spectre-v1-v2" aria-label="Permalink to &quot;Spectre v1 / v2&quot;">​</a></h1><div class="epigraph"><p>分支预测让错误路径上的 load 仍然发生；架构状态回滚之后，缓存占用还在。v1 是条件方向，v2 是间接目标被训练到错误处。</p><footer>—— 据 Kocher et al., Spectre Attacks, IEEE S&amp;P 2019 整理</footer></div><p><a href="/cs/mttf-redundancy">上一课</a> 管随机翻转。<a href="/cs/speculation-recovery">推测恢复</a> 已写明：cache 填充不随 ROB 冲刷回滚。<a href="/cs/transient-exec">瞬态执行对照</a> 在安全主干点过名。本课在微结构进阶里把 <strong>Spectre v1（边界检查绕过）与 v2（分支目标注入）接到 gshare/BTB</strong>，只讲机制与缓解，不给探测程序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/gshare-predictor">gshare</a> 与 <a href="/cs/indirect-branch-predict">间接预测</a> 故意在核对前取指执行。错误路径上的 load 可以用推测值当索引去碰 cache。<a href="/cs/speculation-recovery">恢复</a> 丢掉寄存器写，不丢 L1 占用。缺口不是再加 ECC，而是<strong>承认预测器 + cache 是安全边界，而不只是 CPI 旋钮。</strong></p><p><span class="marginnote">术语翻译：BTB（分支目标缓冲）就是一张「这条跳转指令历史上跳到哪」的缓存表。v2 的本质是往这张表里塞错答案，让受害者的间接跳转在权限核对之前先「猜」去错误的地方——预测器从性能部件变成了攻击接口。</span></p><p><span class="marginnote">v1：条件误预测让越界下标在检查失败前执行。v2：间接 BTB/ITT 被训练到错误目标。缓解包括序列化、间接目标隔离、编译器栅栏，皆有性能税。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：敏感下标不按推测值索引；编译器在检查后插入硬序列化（实现相关）。系统：间接分支隔离（每进程 BTB 上下文）、限制跨特权训练。微码可改预测器行为。本课不描述如何训练预测器去越权读。</p>',9)),(E(),s(n,null,{default:e(()=>[c(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRED%5B%22%E6%96%B9%E5%90%91%E6%88%96%E7%9B%AE%E6%A0%87%E9%A2%84%E6%B5%8B%22%5D%20--%3E%20SPEC%5B%22%E9%94%99%E8%AF%AF%E8%B7%AF%E5%BE%84%20load%22%5D%0A%20%20SPEC%20--%3E%20ARCH%5B%22ROB%20%E5%86%B2%E5%88%B7%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20SPEC%20--%3E%20CACHE%5B%22cache%20%E5%8D%A0%E7%94%A8%E7%95%99%E4%B8%8B%22%5D%0A%20%20CACHE%20--%3E%20MIT%5B%22%E9%9A%94%E7%A6%BB%20%2F%20%E5%BA%8F%E5%88%97%E5%8C%96%20%2F%20%E9%99%90%E5%88%B6%E8%AE%AD%E7%BB%83%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 <a href="/cs/fence-cost">fence 代价</a> 直接冲突：关掉推测就回到深管线的误预测损失。<a href="/cs/loop-predictor">循环器</a> 与 TAGE 越准，攻击面的「可用错误路径」形态在变，但不会消失。SMT 共核共享预测器与 cache，信任域应视为合并。</p><p>retpoline 一类把间接跳转改成不会走被污染 BTB 的序列，是 v2 的软件补丁，前端带宽与 <a href="/cs/uop-cache">uop cache</a> 命中都会变差。硬件间接隔离之后可以关掉部分补丁。</p>',3)),(E(),s(n,null,{default:e(()=>[c(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20V1%5B%22v1%EF%BC%9A%E6%9D%A1%E4%BB%B6%E6%96%B9%E5%90%91%E9%A2%84%E6%B5%8B%E9%94%99%22%5D%20--%3E%20PATH%5B%22%E9%94%99%E8%AF%AF%E8%B7%AF%E5%BE%84%E4%B8%8A%E7%9A%84%E8%B6%8A%E7%95%8C%20load%22%5D%0A%20%20V2%5B%22v2%EF%BC%9A%E9%97%B4%E6%8E%A5%E7%9B%AE%E6%A0%87%E8%A2%AB%E8%AE%AD%E7%BB%83%E9%94%99%22%5D%20--%3E%20PATH%0A%20%20PATH%20--%3E%20IDX%5B%22%E6%8E%A8%E6%B5%8B%E5%80%BC%E5%BD%93%E4%B8%8B%E6%A0%87%E8%AE%BF%E9%97%AE%20cache%22%5D%0A%20%20IDX%20--%3E%20OCC%5B%22%E7%BC%93%E5%AD%98%E8%A1%8C%E5%8D%A0%E7%94%A8%20%3D%20%E7%A7%98%E5%AF%86%E7%9A%84%E5%87%BD%E6%95%B0%22%5D%0A%20%20OCC%20--%3E%20TS%5B%22%E6%97%B6%E5%BA%8F%E5%B7%AE%E5%8D%B3%E6%B3%84%E6%BC%8F%22%5D%0A%20%20TS%20--%3E%20FIX%5B%22v1%20%E8%A1%A5%E6%A3%80%E6%9F%A5%E5%90%8E%E6%A0%85%E6%A0%8F%EF%BC%9Bv2%20%E9%9A%94%E7%A6%BB%20BTB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>这张图回答的是：v1 与 v2 入口不同（方向预测 vs 目标训练）、出口相同（缓存占用变时序差）——所以缓解必须分别堵两个入口，而不是堵中间那条公共通路。</p><p><span class="marginnote">数字实例：一次分支误预测的冲刷损失约 15-20 拍，但错误路径上已执行的几十条指令早已把数据载入 L1——一次 L1 命中只要约 4 拍。攻击者量的是这 4 拍量级的时序差，冲刷本身根本拦不住已经写进缓存的痕迹。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列变体编号大全，不给测量代码。Meltdown 下一课是故障抑制而不是分支预测。KPTI 是 OS 对故障路径的页表药方。Rowhammer 是 DRAM 物理层，再下一课。</p><p><span class="marginnote">常见误区：初学者容易以为 Spectre 与 Meltdown 是同一类问题。Meltdown 靠故障路径绕过权限检查，OS 的页表药方可治；Spectre 利用的是合法的分支预测——任何会预测分支的 CPU 都在攻击面内，只能缓解，没有「修复」这一说。</span></p><p>后课默认：v1/v2 的根是预测 + 不可回滚的 cache。故障路径上的特权检查被乱序绕过，是 Meltdown。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Spectre v1/v2 把分支预测器接到缓存足迹。</li><li>缓解是限制推测与隔离预测器状态，对 CPI 不免费。</li><li>故障抑制路径是下一课 Meltdown。</li><li>出处：Kocher et al., <em>IEEE S&amp;P</em>, 2019。</li></ul>',8))])}const C=A(p,[["render",i]]);export{f as __pageData,C as default};
